// component.ts
export class ListComponent {
  items = Array.from({ length: 500 }, (_, i) => ({ id: i, text: `Item ${i}`, timestamp: Date.now() }));

  trackById(index: number, item: any): number { return item.id; }

  refresh() {
    // Simulate new data with some items changed
    this.items = this.items.map(item =>
      item.id % 50 === 0
        ? { ...item, text: `Updated ${item.id}`, timestamp: Date.now() }
        : item
    );
  }
}

// template.html
<button (click)="refresh()">Refresh</button>
<ul>
  <li *ngFor="let item of items; trackBy: trackById">
    {{ item.text }} - {{ item.timestamp | date:'mediumTime' }}
  </li>
</ul>
